<script setup>
import { inject, toRefs } from 'vue';
import { ccDashboardKey } from '../../../lib/cc-dashboard-context';
import CCPager from '../CCPager.vue';
const { maskPhone, enquiryDate, enquiryLabel, to, page, searching, loading, stages, pages, filters, apply, load, assignSearch, assignSelected, assignTo, assignBusy, assignError, autoTransferStatus, assignRows, assignRecipients, assignAutoRows, toggleAssignLead, selectAllAssign, applyManualAssignment, runAutoTransfer } = toRefs(inject(ccDashboardKey));
</script>

<template>
<section class="cc-card"><header>🔀 Manual Lead Assignment</header><p class="cc-note">Search by mobile number across all dates, select leads, choose an active call-centre agent, then apply.</p><div class="cc-queue-filters"><input v-model="assignSearch" placeholder="Search mobile number across all dates" aria-label="Search assignment leads"></div><p v-if="loading" role="status">Loading leads…</p><div class="tbl-wrap"><table class="cc-simple-table"><thead><tr><th><input class="cc-select-checkbox" type="checkbox" :checked="assignRows.length>0&&assignRows.every(row=>assignSelected.has(row.name))" :indeterminate="assignRows.some(row=>assignSelected.has(row.name))&&!assignRows.every(row=>assignSelected.has(row.name))" aria-label="Select all filtered leads" @change="selectAllAssign($event.target.checked)"></th><th>Lead ID</th><th>Name</th><th>Phone</th><th>Area</th><th>Source</th><th>Owner</th><th>Status</th></tr></thead><tbody><tr v-for="row in assignRows" :key="row.name"><td><input class="cc-select-checkbox" type="checkbox" :checked="assignSelected.has(row.name)" :aria-label="'Select ' +(row.lead_name||row.name)" @change="toggleAssignLead(row.name,$event.target.checked)"></td><td>{{row.name}}</td><td>{{row.lead_name||row.first_name}}<small v-if="enquiryLabel(row)" class="cc-note"> · {{enquiryLabel(row)}} · {{enquiryDate(row)}}</small></td><td>{{maskPhone(row.mobile_no)}}</td><td>{{row.city||'—'}}</td><td>{{row.source||'—'}}</td><td>{{row.lead_owner||'—'}}</td><td>{{row.custom_cc_chat_returned?'New Lead to the Same Agent':(row.custom_cc_stage||row.status)}}</td></tr><tr v-if="!assignRows.length"><td colspan="8">No leads found.</td></tr></tbody></table></div><div class="cc-assign-sticky"><strong>{{assignSelected.size}} leads selected</strong><select v-model="assignTo"><option value="">Choose active agent</option><option v-for="owner in assignRecipients" :key="owner.id" :value="owner.id">{{owner.name}}</option></select><button class="cc-primary" :disabled="assignBusy" @click="applyManualAssignment">{{assignBusy?'Assigning…':'✅ Apply Assignment'}}</button></div><CCPager v-if="searching" :page="page" :pages="pages" :busy="loading" @change="load($event)" /><p v-if="assignError" class="cc-note">{{assignError}}</p></section><section class="cc-card"><header>⚡ Auto Transfer (Round Robin)</header><p class="cc-note">Spread every lead with a selected status across active call-centre agents.</p><div class="cc-queue-filters"><select v-model="autoTransferStatus"><option value="">Select a status</option><option v-for="stage in stages" :key="stage">{{stage}}</option></select><strong>{{assignAutoRows.length}} matching leads</strong><button class="cc-primary" :disabled="assignBusy" @click="runAutoTransfer">{{assignBusy?'Transferring…':'🔀 Auto Transfer'}}</button></div><p>{{assignRecipients.map(owner=>owner.name).join(' · ')||'No active call-centre agents are available.'}}</p></section>
</template>
